#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using Object=UnityEngine.Object;
namespace BorrowedTime.Editor {
[InitializeOnLoad]
public static class BTSkyCityJourneyPlaytest {
 class Step{public int node=-1;public float value;public string label;public Func<bool> ready;public Vector3 point;public bool direct;}
 static BTSkyCityGame game;static List<Step> steps;static int index;static bool running,walk,run,bones,robot;static float since;static double began;static Queue<Vector3> path;static Vector3 goal;static float bestDistance;static float lastProgress;static int approachAttempt;
 static readonly List<string> log=new List<string>();static Quaternion[] baseline;static Transform[] joints;
 static BTSkyCityJourneyPlaytest(){EditorApplication.update+=Tick;}
 public static void StartAtCity(){Application.runInBackground=true;game=Object.FindFirstObjectByType<BTSkyCityGame>();if(!game||!BTJourney.FromTraining||!BTJourney.HasMiracleSeed)throw new Exception("Actual training to Sky City seed transition missing");game.puzzles.testMode=true;game.ResetAll();began=EditorApplication.timeSinceStartup;log.Clear();index=0;since=Time.time;path=null;approachAttempt=0;walk=run=bones=robot=false;running=true;steps=new List<Step>();
  void Node(int n,float value,string label){steps.Add(new Step{node=n,value=value,label=label});}
  Node(0,0,"drain obstruction before generator");Node(1,1,"restore generator with collected time");steps.Add(new Step{label="wait for real access bridge to dock",ready=()=>game.IntroAccess&&game.bridgeA.GetComponent<BTSkyCitySlidingBridge>().movingColliders.All(c=>!c||c.enabled)});
  foreach(float z in new[]{-2f,game.bridgeA.GetComponent<BTSkyCitySlidingBridge>().step*2.5f,game.bridgeA.GetComponent<BTSkyCitySlidingBridge>().step*5+1.4f})steps.Add(new Step{label="walk deployed intro bridge at "+z,point=game.bridgeA.TransformPoint(new Vector3(0,0,z)),direct=true});
  Node(2,0,"remove water obstruction");Node(8,1,"seal leaking pipe");Node(3,1,"restore waterwheel");steps.Add(new Step{label="wait for clock door to open",ready=()=>game.puzzles.WaterReady&&Time.time-since>3});
  Node(4,0,"remove clock obstruction");Node(5,1,"restore gear teeth");steps.Add(new Step{label="wait for physical freight access bridge",ready=()=>game.puzzles.ClockReady&&game.puzzles.accessBridge.movingColliders.All(c=>!c||c.enabled)});
  steps.Add(new Step{label="reach clock courtyard approach",point=game.puzzles.accessBridge.transform.position-Vector3.right*3+Vector3.forward*11});steps.Add(new Step{label="walk supported courtyard approach",point=game.puzzles.accessBridge.transform.position-Vector3.right*3,direct=true});steps.Add(new Step{label="turn into ramp front entrance",point=game.puzzles.accessBridge.transform.position,direct=true});foreach(float z in new[]{game.puzzles.accessBridge.step*2.5f,game.puzzles.accessBridge.step*5+1.4f})steps.Add(new Step{label="walk deployed control ramp at "+z,point=game.puzzles.accessBridge.transform.TransformPoint(new Vector3(0,0,z)),direct=true});
  Node(11,0,"collect remaining time from emergency cell");Node(10,1,"repair bridge lock while support remains");Node(6,0,"release support after lock repair");steps.Add(new Step{label="wait for factory bridge and door docking",ready=()=>game.FactoryDocked&&Time.time-since>7});
  foreach(float z in new[]{game.puzzles.accessBridge.step*5+1.4f,game.puzzles.accessBridge.step*2.5f,0f})steps.Add(new Step{label="walk back down control ramp at "+z,point=game.puzzles.accessBridge.transform.TransformPoint(new Vector3(0,0,z)),direct=true});steps.Add(new Step{label="turn back onto courtyard approach",point=game.puzzles.accessBridge.transform.position-Vector3.right*3,direct=true});steps.Add(new Step{label="return across supported courtyard approach",point=game.puzzles.accessBridge.transform.position-Vector3.right*3+Vector3.forward*11,direct=true});steps.Add(new Step{label="reach factory bridge entrance",point=game.bridgeB.TransformPoint(new Vector3(0,0,-2))});foreach(float z in new[]{game.bridgeB.GetComponent<BTSkyCitySlidingBridge>().step*2.5f,game.bridgeB.GetComponent<BTSkyCitySlidingBridge>().step*5+1.4f})steps.Add(new Step{label="walk deployed factory bridge at "+z,point=game.bridgeB.TransformPoint(new Vector3(0,0,z)),direct=true});
  steps.Add(new Step{label="walk across real bridge to factory entrance",point=new Vector3(game.door.position.x+2,0,game.door.position.z)});
  game.inputOverride=Input;var bridge=game.GetComponent<BTSkyCityCharacterBridge>();joints=bridge.hero.animator.GetComponentsInChildren<Transform>();baseline=joints.Select(t=>t.localRotation).ToArray();Note("START active Sky City controller, real scroll input, no inventory or puzzle-state grants");
 }
 static void Note(string s){log.Add((EditorApplication.timeSinceStartup-began).ToString("F2")+"s | "+s);File.WriteAllLines(BTJourneyDirectionChecks.Out+"/SkyCityRoute.txt",log);}
 static void Next(){Note("PASS "+index+" "+steps[index].label+" energy="+game.energy.ToString("F1"));index++;since=Time.time;path=null;approachAttempt=0;bestDistance=10000;lastProgress=Time.time;}
 static void Fail(Exception e){Note("FAIL "+e);running=false;if(game)game.inputOverride=null;BTSaveGame.CancelPendingContinue();BTSaveGame.TestPathOverride=null;EditorApplication.isPlaying=false;}
 static void Tick(){if(!running||!EditorApplication.isPlaying)return;try{
  if(Object.FindFirstObjectByType<BTFactoryGame>()){if(!walk||!run||!bones||!robot)throw new Exception("City presentation evidence missing Walk="+walk+" Run="+run+" Bones="+bones+" Robo="+robot);Note("PASS Walk and Run states, animated joint motion and Robo visible alongside player; actual Sky City → Factory carrying seed");running=false;BTFactoryCampaignRoute.StartWaiting();return;}
  if(!game)return;var bridge=game.GetComponent<BTSkyCityCharacterBridge>();walk|=bridge.hero.currentPose=="Walk";run|=bridge.hero.currentPose=="Run";for(int i=0;i<joints.Length;i++)if(Quaternion.Angle(joints[i].localRotation,baseline[i])>4)bones=true;
  var p=game.cam.GetComponent<Camera>().WorldToViewportPoint(bridge.roboRoot.position);if(Vector3.Distance(game.player.position,bridge.roboRoot.position)<3.5f&&p.z>0&&p.x>.02f&&p.x<.98f&&p.y>.02f&&p.y<.98f)robot=true;
  if(Time.time-since>65)throw new Exception("Sky City timeout step="+index+" pos="+game.player.position+" target="+game.FocusedNode+" feedback="+game.Feedback+" values="+string.Join(",",game.nodes.Take(12).Select(n=>n.value.ToString("F6")))+" energy="+game.energy);
 }catch(Exception e){Fail(e);}}
 static bool Surface(float x,float z,out Vector3 point){point=new Vector3(x,0,z);foreach(var hit in Physics.RaycastAll(new Vector3(x,14,z),Vector3.down,22,~(1<<2),QueryTriggerInteraction.Ignore).OrderBy(h=>Mathf.Abs(h.point.y-(game.player.position.y>2?3.4f:0f)))){if(hit.collider==game.controller||hit.normal.y<.65f||hit.point.y>3.55f||hit.collider.GetComponentInParent<BTSkyCityAgeVisual>())continue;var p=hit.point+Vector3.up*.04f;if(Physics.OverlapCapsule(p+Vector3.up*.75f,p+Vector3.up*1.52f,.34f,~(1<<2),QueryTriggerInteraction.Ignore).Any(c=>c!=game.controller))continue;point=p;return true;}return false;}
 static bool Floor(Vector2Int cell,out Vector3 point)=>Surface(cell.x,cell.y,out point);
 static bool Connected(Vector3 a,Vector3 b){float previous=a.y;for(int i=1;i<=5;i++){var p=Vector3.Lerp(a,b,i/5f);if(!Surface(p.x,p.z,out var surface)||Mathf.Abs(surface.y-previous)>.40f)return false;previous=surface.y;}return true;}
 static Vector2Int Cell(Vector3 p)=>new Vector2Int(Mathf.RoundToInt(p.x),Mathf.RoundToInt(p.z));
 static Queue<Vector3> Path(Vector3 start,Vector3 finish){
  var a=Cell(start);var b=Cell(finish);var open=new List<Vector2Int>{a};var came=new Dictionary<Vector2Int,Vector2Int>();var cost=new Dictionary<Vector2Int,float>{{a,0}};var positions=new Dictionary<Vector2Int,Vector3>{{a,start}};var free=new Dictionary<Vector2Int,bool>();Vector2Int found=a;int visits=0;
  while(open.Count>0&&visits++<24000){int best=0;float score=float.MaxValue;for(int i=0;i<open.Count;i++){float f=cost[open[i]]+Vector2Int.Distance(open[i],b);if(f<score){score=f;best=i;}}var n=open[best];open.RemoveAt(best);if(Vector2Int.Distance(n,b)<1.2f){found=n;break;}
   foreach(var d in new[]{Vector2Int.left,Vector2Int.right,Vector2Int.up,Vector2Int.down}){var q=n+d;if(q.x< -100||q.x>125||q.y< -42||q.y>42)continue;if(!free.ContainsKey(q)){free[q]=Floor(q,out var pt);positions[q]=pt;}if(!free[q]||Mathf.Abs(positions[q].y-positions[n].y)>.60f||!Connected(positions[n],positions[q]))continue;float c=cost[n]+1;if(cost.ContainsKey(q)&&cost[q]<=c)continue;cost[q]=c;came[q]=n;if(!open.Contains(q))open.Add(q);}
  }
  if(found==a&&Vector2Int.Distance(a,b)>2)throw new Exception("No supported capsule path "+start+" -> "+finish+" for "+steps[index].label+" visits="+visits+" reachable x="+cost.Keys.Min(c=>c.x)+".."+cost.Keys.Max(c=>c.x)+" z="+cost.Keys.Min(c=>c.y)+".."+cost.Keys.Max(c=>c.y));
  var list=new List<Vector3>{finish};var at=found;while(at!=a){list.Add(positions[at]);if(!came.ContainsKey(at))break;at=came[at];}list.Reverse();return new Queue<Vector3>(list);
 }
 static bool Move(Vector3 to,ref BTPlayer.FrameInput f){var d=to-game.player.position;d.y=0;if(d.magnitude<.45f){path=null;return true;}if(path==null||Vector3.Distance(goal,to)>.1f){goal=to;try{path=Path(game.player.position,to);}catch(Exception){if(steps[index].node<0||approachAttempt++>45)throw;goal=Approach(steps[index].node);path=null;return false;}bestDistance=10000;lastProgress=Time.time;}
  while(path.Count>1){var q=path.Peek()-game.player.position;q.y=0;if(q.magnitude>.35f)break;path.Dequeue();bestDistance=10000;lastProgress=Time.time;}
  var delta=(path.Count>0?path.Peek():to)-game.player.position;delta.y=0;if(delta.magnitude<bestDistance-.02f){bestDistance=delta.magnitude;lastProgress=Time.time;}if(Time.time-lastProgress>5)throw new Exception("Controller obstructed at "+game.player.position+" waypoint="+(path.Count>0?path.Peek():to));var local=Quaternion.Inverse(Quaternion.Euler(0,game.ViewYaw,0))*delta.normalized;f.sprint=index%2==1;f.move=new Vector2(local.x,local.z)*Mathf.Min(1,delta.magnitude/(Mathf.Max(.001f,Time.deltaTime)*(f.sprint?8:5.2f)));return false;}
 static Vector3 Approach(int node){Vector3 centre=game.AimPoint(node);var candidates=new List<Vector3>();for(int ring=0;ring<5;ring++)for(int i=0;i<16;i++){float a=i*Mathf.PI/8;Vector3 q=centre+new Vector3(Mathf.Sin(a)*(Mathf.Min(6,2.5f+ring)),0,Mathf.Cos(a)*(Mathf.Min(6,2.5f+ring)));if(!Floor(Cell(q),out var floor))continue;if(Mathf.Abs(floor.y-centre.y)>4||Mathf.Abs(floor.y-(game.nodes[node].model.position.y>3?3.4f:0f))>.5f)continue;var from=floor+Vector3.up*1.6f;if(Physics.Linecast(from,centre,out var hit,~(1<<2),QueryTriggerInteraction.Collide)&&hit.transform!=game.nodes[node].model&&!hit.transform.IsChildOf(game.nodes[node].model))continue;candidates.Add(floor);}
  var sorted=candidates.OrderBy(p=>Vector3.Distance(p,game.player.position)+Mathf.Max(0,p.y-(game.nodes[node].model.position.y>3?3.4f:0f)-.1f)*20).ToArray();if(sorted.Length==0)throw new Exception("No target approach "+node);return sorted[Mathf.Min(approachAttempt,sorted.Length-1)];}
 static BTPlayer.FrameInput Input(){var f=new BTPlayer.FrameInput();if(!running||!game)return f;try{
  if(index>=steps.Count){f.interact=true;return f;}var step=steps[index];if(step.ready!=null){if(step.ready())Next();return f;}
  if(step.node<0){if(step.direct){Vector3 d=step.point-game.player.position;d.y=0;if(d.magnitude<.35f)Next();else{var q=Quaternion.Inverse(Quaternion.Euler(0,game.ViewYaw,0))*d.normalized;f.move=new Vector2(q.x,q.z)*Mathf.Min(1,d.magnitude/(Mathf.Max(.001f,Time.deltaTime)*5.2f));}}else if(Move(step.point,ref f))Next();return f;}
  if(Mathf.Abs(game.nodes[step.node].value-step.value)<.001f){Next();return f;}
  if(path==null&&Vector3.Distance(goal,game.player.position)>.55f)goal=Approach(step.node);if(goal==Vector3.zero||Vector3.Distance(goal,game.nodes[step.node].model.position)>7)goal=Approach(step.node);
  if(Move(goal,ref f)){Vector3 d=game.AimPoint(step.node)-game.cam.position;float yaw=Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg,pitch=-Mathf.Atan2(d.y,new Vector2(d.x,d.z).magnitude)*Mathf.Rad2Deg;f.look=new Vector2(Mathf.DeltaAngle(game.ViewYaw,yaw)*.6f/.12f,-(pitch-game.ViewPitch)*.6f/.1f);if(game.FocusedNode==step.node)f.scroll=game.nodes[step.node].value>step.value?-120:120;else if(Time.time-lastProgress>4){approachAttempt++;goal=Approach(step.node);path=null;lastProgress=Time.time;}}
 }catch(Exception e){Fail(e);}return f;}
}}
#endif
